WITH latest_match AS (SELECT s.*, latest.order_order_date, latest.amount FROM stores s JOIN LATERAL (SELECT c.order_date AS order_order_date, c.amount FROM orders c WHERE c.store_id = s.id ORDER BY c.amount DESC, c.id DESC LIMIT 1) latest ON TRUE) SELECT city, CASE WHEN amount >= 1570 THEN 'LARGE' ELSE 'SMALL' END AS amount_tier, DATE_TRUNC('QUARTER', order_order_date) AS quarter_start, COUNT(CASE WHEN city = 'London' THEN 1 END) AS london_count, APPROX_PERCENTILE(amount, 0.5) AS amount_p50 FROM latest_match GROUP BY GROUPING SETS ((city, CASE WHEN amount >= 1570 THEN 'LARGE' ELSE 'SMALL' END, DATE_TRUNC('QUARTER', order_order_date)), (city, CASE WHEN amount >= 1570 THEN 'LARGE' ELSE 'SMALL' END), (city)) ORDER BY amount_tier DESC NULLS LAST
